import json,hashlib
from pathlib import Path
edits={
'app/leading/journey/page.tsx':[
('Grow as a leader at your own pace: learn, reflect, try it in your real work, note what changed, and go around again. Nobody is enrolled and nothing is recorded.','Connect leadership learning with a work decision, reflection and follow-up. This optional path does not enroll you in assigned training; related learning tools explain what they save.'),
('Most of what makes someone a better leader comes from trying things in real work. Some comes from other people: a colleague, a mentor, a team. A small part comes from lessons. So the lessons here are short, and each one leads to something to try.','Combine structured learning with workplace experience and feedback from colleagues. A lesson can introduce a concept; applying it requires attention to the situation, your authority and the people affected. Review what happened before deciding what to retain or change.'),
('Reflection is what turns a lesson into a change. A few lines are enough, and three questions carry most of it: what happened, why it matters, and what you will do next.','Use reflection to compare your intention with what happened. Record the observations, their significance and what remains uncertain, then decide what to retain, revise or refer to someone with the relevant responsibility.'),
('They do not count toward required training unless your manager, director or agency leadership approves an exception.','Confirm any required-training credit through the agency process responsible for that requirement; do not assume that completing an external course satisfies it.'),
('There is nothing to submit, and nothing here is counted or rated. If you want something to bring to a development conversation, download your action plans and reflections from','This optional path has no completion submission or supervisor score report. Related lessons may save progress or practice responses in your browser profile. If you want something to bring to a development conversation, review and download your action plans and reflections from')],
'app/leading/how-this-works/page.tsx':[
('There is no team view, no assignments and no scores.','This leadership area does not give supervisors a learner scoreboard or assign these optional courses.'),
('A supervisor cannot see who opened a course, how far they got or what they answered. Neither can you.','This area does not provide supervisors with individual course visits, progress or answers. Anyone using the same browser profile may still see information saved there.'),
('Your progress stays in your browser. That includes your place on a suggested path, your lesson progress and your practice answers.','Features that save a place on a suggested path, lesson progress or practice answers keep those items in this browser profile when storage is available.'),
('Nothing is sent to a supervisor or employer.','The learning-progress feature does not send those saved items to supervisors or program staff. Exporting or sharing a copy is a separate action.'),
('Anyone using the same computer and browser could see it. You can clear it at any time.','Anyone using the same browser profile may see saved items. Use the relevant feature to clear them; downloaded, printed or shared copies remain separate.'),
('The one exception to voluntary use','Required responsibilities and optional learning'),
('The Equity Analysis Toolkit is required of all staff of the Minnesota Department of Human Services, regardless of status, so it is marked &ldquo;{REQUIRED_COURSE_LABEL}&rdquo; wherever it is listed here. This app does not assign it or report on who has taken it.','The label &ldquo;{REQUIRED_COURSE_LABEL}&rdquo; refers to the agency responsibility associated with the Equity Analysis Toolkit. This local companion course does not assign or certify required agency training. Follow the designated agency process for training and the applicable policy requirements for equity analysis.')],
'app/learn/equity-toolkit/goals/page.tsx':[
('The program constitution governs how this resource supports the whole One DSD program.','The proposed program charter describes how this resource fits within One DSD learning. It does not replace applicable policy, assigned responsibilities or decision authority.')],
'components/my-view-client.tsx':[
('This also removes your private practice plans, structural-review draft, practice reflection, saved resources, and saved places in the self-directed courses from this browser. Downloaded files and protected operational records are not deleted.','This also removes the practice plans, structural-review draft, practice reflection, saved resources and course places managed by My work from this browser profile. Other features may have separate notes or records to clear. Downloaded files and operational records are not deleted.'),
('Your saved learning information and practice drafts have been removed from this browser. Downloaded files and protected operational records are unchanged.','The saved items managed by My work have been removed from this browser profile. Other features may retain separate notes. Downloaded files and operational records are unchanged.'),
('Some saved information could not be deleted. It may still be in this browser. Downloaded files and protected operational records are unchanged. Please try again.','Some saved items could not be deleted and may remain in this browser profile. Downloaded files and operational records are unchanged. Please try again.'),
('Some saved information could not be opened. It is still on this device. You can try opening the related page again or remove the saved information here.','Some saved information could not be opened. It remains in this browser profile. Try the related page again or use the available removal controls.'),
('Deleting all private information also removes your practice plans, practice reflection, and saved resources from this browser. Files you have downloaded remain on your device.','This control removes the saved learning and practice items managed by My work from this browser profile. Some features, including CLAS working notes, have their own clearing controls. Downloaded, printed and shared copies are unchanged.')]
}
records=[]
for file,pairs in edits.items():
 s=Path(file).read_text(encoding='utf8');changes=[]
 for before,after in pairs:
  assert s.count(before)==1,(file,before)
  changes.append({'before':before,'after':after})
 records.append({'file':file,'sourceSha256':hashlib.sha256(Path(file).read_bytes()).hexdigest(),'original':s,'changes':changes})
Path('output/leading-privacy-proposal.json').write_text(json.dumps({'records':records,'basis':'Full route/component and browser-storage registry read. My work clearing covers registered keys; CLAS notes are outside that list. Preserve official agency training duties, proposed charter status, and evidence-led retain/revise decisions. No new legal claim or policy exception.'},ensure_ascii=False,indent=2)+'\n',encoding='utf8')
